SELECT r.id, r.username, r.display_name, r.email, r.provider, r.subject, r.hash_ip, r.timezone, r.default_agent_ref, r.default_model_ref, r.default_embedder_ref, r.settings, r.disabled, r.created_at, r.updated_at FROM (SELECT data_rows.id, data_rows.username, data_rows.display_name, data_rows.email, data_rows.provider, data_rows.subject, data_rows.hash_ip, data_rows.timezone, data_rows.default_agent_ref, data_rows.default_model_ref, data_rows.default_embedder_ref, data_rows.settings, data_rows.disabled, data_rows.created_at, data_rows.updated_at FROM  (SELECT `id`, `username`, `display_name`, `email`, `provider`, `subject`, `hash_ip`, `timezone`, `default_agent_ref`, `default_model_ref`, `default_embedder_ref`, `settings`, `disabled`, `created_at`, `updated_at` FROM users)  data_rows) r WHERE $criteria.CompositeIn("r", $WriterKeys)